package studio.shiren.mobile;
import java.io.*;import java.nio.*;
import org.jcodec.codecs.h264.H264Encoder;import org.jcodec.codecs.h264.encode.DumbRateControl;import org.jcodec.codecs.h264.io.model.*;import org.jcodec.common.*;import org.jcodec.common.io.*;import org.jcodec.common.model.*;import org.jcodec.containers.mp4.muxer.MP4Muxer;
/** CPU fallback with explicit limited-range Rec.709 signalling. */
final class PortableH264 implements AutoCloseable {
 private final SeekableByteChannel channel;private final MP4Muxer muxer;private final MuxerTrack track;private final H264Encoder encoder;private final Picture picture;private final ByteBuffer encoded;private final int fps;private boolean finished=false;
 /* 初始化便携 H.264 编码器。 */ PortableH264(File file,int w,int h,int rate)throws Exception{fps=rate;channel=NIOUtils.writableChannel(file);muxer=MP4Muxer.createMP4MuxerToChannel(channel);track=muxer.addVideoTrack(Codec.H264,VideoCodecMeta.createSimpleVideoCodecMeta(new Size(w,h),ColorSpace.YUV420J));encoder=new H264Encoder(new DumbRateControl()){/* 初始化便携编码器的序列参数集。 */ @Override public SeqParameterSet initSPS(Size size){SeqParameterSet s=super.initSPS(size);s.levelIdc=w*h<=1280*720?(rate<=30?31:32):(rate<=30?40:42);s.constraintSet0Flag=true;s.constraintSet1Flag=true;VUIParameters v=new VUIParameters();v.videoSignalTypePresentFlag=true;v.videoFormat=5;v.videoFullRangeFlag=false;v.colourDescriptionPresentFlag=true;v.colourPrimaries=1;v.transferCharacteristics=1;v.matrixCoefficients=1;v.chromaLocInfoPresentFlag=true;v.chromaSampleLocTypeTopField=1;v.chromaSampleLocTypeBottomField=1;v.timingInfoPresentFlag=true;v.numUnitsInTick=1;v.timeScale=rate*2;v.fixedFrameRateFlag=true;s.vuiParams=v;return s;}};encoder.setKeyInterval(rate);encoder.setMotionSearchRange(4);picture=Picture.create(w,h,ColorSpace.YUV420J);encoded=ByteBuffer.allocate(w*h*6+65536);}
 /* 追加当前视频帧或音轨数据并维护时间戳。 */ void append(byte[] i420,int frame)throws Exception{int offset=0;for(byte[] plane:picture.getData()){for(int i=0;i<plane.length;i++)plane[i]=(byte)(i420[offset+i]^0x80);offset+=plane.length;}encoded.clear();org.jcodec.common.VideoEncoder.EncodedFrame packet=encoder.encodeFrame(picture,encoded);track.addFrame(Packet.createPacket(NIOUtils.clone(packet.getData()),frame,fps,1,frame,packet.isKeyFrame()?Packet.FrameType.KEY:Packet.FrameType.INTER,null));}
 /* 完成当前任务并释放编码或缓存资源。 */ void finish()throws Exception{if(!finished){muxer.finish();finished=true;channel.close();}}
 /* 关闭当前对象持有的资源，避免重复占用文件、线程或设备。 */ public void close(){try{channel.close();}catch(Exception ignored){}}
}
